"""Avalia sentidos por NPC e mudanças observáveis; sem roteiro de dungeon ou IA."""

from dataclasses import replace
from copy import deepcopy
from decimal import Decimal
import logging

from trama.actions import ActionError
from trama.application.routing import path_to_cells
from trama.dice import roll_d20
from trama.distances import CELL_METERS
from trama.movement import MovementError
from trama.perception import CONVERSATION_HEARING_MULTIPLIER, Noise, Observer, Senses
from trama.spatial import Position
from trama.vision import line_of_sight

logger = logging.getLogger(__name__)


class PerceptionRangeError(ActionError):
    """Nenhum sentido disponível alcança o alvo da busca."""


def distance(a, b):
    return CELL_METERS * max(abs(a.x - b.x), abs(a.y - b.y))


class PerceptionSystem:
    def __init__(self, session):
        self.session = session
        self.hidden_total = None
        self.awareness = {}
        self.awakened = set()
        self.searches = set()
        self.last_search = {}
        self.revision = 0
        self._observation_key = (session.state.position, session.scene,
                                 tuple((o.id, o.position) for o in self.observers()))
        self._sound_cache = {}
        self._sound_barriers = {}
        self._scene_key = None

    def observers(self):
        s = self.session
        return (*[c for c in s.creatures if s.encounter.states[c.id].hp > 0], *s.observers)

    def observer(self, actor_id):
        observer = next((o for o in self.observers() if o.id == actor_id), None)
        if observer is None:
            raise ActionError('Não há NPC consciente e existente com esses sentidos.')
        return observer

    def bonus(self, observer):
        if observer.senses.perception_bonus is not None:
            return observer.senses.perception_bonus
        return self.session.encounter.sheets[observer.id].skill_bonus('perception')

    def sleeping(self, observer):
        return observer.senses.sleeping and observer.id not in self.awakened

    def sees(self, observer, target):
        senses, s = observer.senses, self.session
        if self.sleeping(observer) or not senses.can_see:
            return False
        d = distance(observer.position, target)
        if senses.sight_range_meters is not None and d > senses.sight_range_meters:
            return False
        dark = s.scene.dark if s.scene else frozenset()
        if senses.darkvision_meters:
            dark = frozenset(p for p in dark if distance(observer.position, p) > senses.darkvision_meters)
        opaque = s.scene.opaque if s.scene else s.grid.blocked
        return target not in dark and line_of_sight(observer.position, target, opaque | dark)

    def sound_distance(self, origin, target):
        s = self.session
        key = (s.scene, s.grid)
        if key != self._scene_key:
            self._sound_cache.clear()
            self._sound_barriers.clear()
            self._scene_key = key
        pair = (origin, target)
        if pair not in self._sound_cache:
            if s.scene:
                passages = frozenset(p.position for p in s.scene.passages)
                grid = replace(s.scene.grid, blocked=s.scene.grid.blocked - passages, difficult=frozenset())
            else:
                grid = replace(s.grid, difficult=frozenset())
            # Objetos não fecham o ar de uma casa; paredes continuam sólidas.
            try:
                path = path_to_cells(grid, origin, frozenset({target}))
                doors = {p.position for p in s.scene.passages if p.kind == 'door' and not p.is_open} if s.scene else set()
                self._sound_cache[pair] = len(path) * CELL_METERS + sum(Decimal('6') for p in path if p in doors)
                self._sound_barriers[pair] = tuple(sorted(p.id for p in s.scene.passages
                    if p.position in path and p.position in doors)) if s.scene else ()
            except MovementError:
                self._sound_cache[pair] = None
                self._sound_barriers[pair] = ()
        return self._sound_cache[pair]

    def sound_barriers(self, origin, target):
        self.sound_distance(origin, target)
        return self._sound_barriers[(origin, target)]

    def hears(self, observer, noise, *, waking=False, adjudicate=True):
        senses = observer.senses
        if not senses.can_hear or observer.id == noise.actor_id:
            return False
        reach = (senses.wake_range_meters if waking else senses.hearing_range_meters) * noise.multiplier
        if (not waking and noise.speech and noise.volume == 'normal'
                and self._mutual_sight(observer, noise)):
            reach *= CONVERSATION_HEARING_MULTIPLIER
        if distance(observer.position, noise.position) > reach:
            return False
        actual = self.sound_distance(noise.position, observer.position)
        if actual is None or actual > reach:
            return False
        if waking or not adjudicate:
            return True
        decision = self.session.adjudication.hearing(observer, noise, self.sound_barriers(noise.position, observer.position))
        hidden_dc = self.hidden_total if noise.actor_id == self.session.encounter.player_id else None
        if decision is None:
            return hidden_dc is None or senses.passive(self.bonus(observer)) >= hidden_dc
        total = dc = None
        heard = decision.outcome == 'automatic'
        if decision.outcome == 'check' or (hidden_dc is not None and decision.outcome != 'impossible'):
            dc = hidden_dc if hidden_dc is not None else decision.dc
            senses = observer.senses
            advantage = senses.advantage or decision.advantage
            disadvantage = senses.disadvantage or decision.disadvantage
            total = 10 + self.bonus(observer) + (5 if advantage and not disadvantage else -5 if disadvantage and not advantage else 0)
            heard = total >= dc
        self.session.adjudication.record_hearing(observer, noise, decision, total, dc, heard)
        return heard

    def _mutual_sight(self, listener, noise):
        """Contato visual atual; lembrança de um interlocutor não amplia audição."""
        s = self.session
        if noise.actor_id == s.encounter.player_id:
            speaker = Observer(noise.actor_id, 'Jogador', s.state.position, Senses(perception_bonus=0))
        else:
            speaker = next((o for o in self.observers() if o.id == noise.actor_id), None)
        return (speaker is not None and speaker.position == noise.position
                and self.sees(listener, speaker.position) and self.sees(speaker, listener.position))

    def _record(self, observer, target_id, level, sense, position, reason):
        previous = self.awareness.get(observer.id, {}).get(target_id)
        if previous and {'heard': 1, 'located': 2, 'seen': 3}[previous['level']] > {'heard': 1, 'located': 2, 'seen': 3}[level]:
            return None  # Ouvir de novo não apaga uma localização já conhecida.
        record = dict(level=level, sense=sense,
                      position=([position.x + 1, position.y + 1] if level in {'seen', 'located'} else None),
                      visible=level == 'seen')
        self.awareness.setdefault(observer.id, {})[target_id] = record
        if previous and previous['level'] == level and (level != 'seen' or previous['visible']):
            return None
        return dict(operation='perception_detected', actor_id=observer.id, target_id=target_id,
                    **record, changed=True, perceptible=False, reason=reason)

    def evaluate(self, noise=None):
        s, events = self.session, []
        if noise is not None and noise.speech:
            # Notar a voz não implica compreender as palavras. A comunicação
            # avalia o conteúdo separadamente, antes de publicar este estímulo.
            noise = replace(noise, speech=False)
        player = s.encounter.player_id
        initial_hidden = self.hidden_total
        observers = self.observers()
        key = (s.state.position, s.scene, tuple((o.id, o.position) for o in observers))
        if key != self._observation_key or (noise is not None and noise.actor_id == player):
            self.revision += 1
            self._observation_key = key
        for observer in observers:
            if self.sleeping(observer):
                if noise is None or not self.hears(observer, noise, waking=True):
                    continue
                self.awakened.add(observer.id)
                events.append(dict(operation='awakened', actor_id=observer.id, target_id=noise.actor_id,
                                   changed=True, perceptible=False, reason=noise.reason))
            visible = self.sees(observer, s.state.position)
            old = self.awareness.get(observer.id, {}).get(player)
            if old:
                old['visible'] = visible and old['visible']
            if visible:
                # Sair da cobertura para exposição evidente não é invisibilidade mágica.
                if getattr(observer, 'hostile', False):
                    self.hidden_total = None
                event = self._record(observer, player, 'seen', 'sight', s.state.position, 'Contato visual livre.')
                if event:
                    events.append(event)
            if noise is not None and self.hears(observer, noise):
                if noise.actor_id == player and visible:
                    continue
                hidden = initial_hidden if noise.actor_id == player else None
                level = 'located' if hidden is not None else 'heard'
                if hidden is not None and getattr(observer, 'hostile', False):
                    self.hidden_total = None
                event = self._record(observer, noise.actor_id, level, 'hearing', noise.position, noise.reason)
                if event:
                    events.append(event)
        return tuple(events)

    def can_hide(self):
        s = self.session
        enemies = [o for o in self.observers() if getattr(o, 'hostile', False)]
        if any(self.sees(o, s.state.position) for o in enemies):
            return False
        opaque = s.scene.opaque if s.scene else s.grid.blocked
        dark = s.scene.dark if s.scene else frozenset()
        return (s.state.position in dark or any(distance(s.state.position, p) <= CELL_METERS for p in opaque)
                or any(not line_of_sight(o.position, s.state.position, opaque) for o in enemies))

    def search(self, actor_id):
        s = self.session
        observer = self.observer(actor_id)
        if self.sleeping(observer):
            raise ActionError('Um NPC dormindo não pode realizar uma busca consciente.')
        if actor_id in s.encounter.sheets:
            s.encounter.require_turn(actor_id)
        elif s.encounter.combat:
            raise ActionError('Esse NPC não participa dos turnos de combate.')
        signature = (actor_id, observer.position, s.state.position, s.scene, self.hidden_total, self.revision,
                     s.encounter.combat.round if s.encounter.combat else None)
        if signature in self.searches:
            raise ActionError('A mesma busca já foi resolvida; é necessária uma mudança relevante ou novo turno.')
        visible = self.sees(observer, s.state.position)
        audible = self.hears(observer, Noise(s.encounter.player_id, s.state.position,
                            'quiet' if self.hidden_total is not None else 'normal', 'Presença do jogador.'), adjudicate=False)
        hearing = s.adjudication.hearing(observer, Noise(s.encounter.player_id, s.state.position,
            'quiet' if self.hidden_total is not None else 'normal'), self.sound_barriers(s.state.position, observer.position)) if audible else None
        if hearing and hearing.outcome == 'impossible':
            audible = False
        if not visible and not audible:
            raise PerceptionRangeError('A busca não alcança o jogador por nenhum sentido disponível.')
        dc = self.hidden_total
        if dc is None:
            return dict(operation='search', actor_id=actor_id, changed=False, perceptible=False,
                        found=visible or audible, automatic=True, reason='Não há ocultação que exija teste.')
        if s.encounter.combat:
            budget = s.encounter.budgets[actor_id].spend_action()
        else:
            budget = None
        dim = s.scene.dim if s.scene else frozenset()
        impaired = visible and not audible and s.state.position in dim
        roll = roll_d20(s.encounter.roller, self.bonus(observer),
            advantage=observer.senses.advantage or bool(not visible and hearing and hearing.advantage),
            disadvantage=observer.senses.disadvantage or impaired or bool(not visible and hearing and hearing.disadvantage))
        self.searches.add(signature)
        if budget is not None:
            s.encounter.budgets[actor_id] = budget
        found = roll.total >= dc
        if found:
            self.hidden_total = None
            event = self._record(observer, s.encounter.player_id, 'seen' if visible else 'located',
                                 'sight' if visible else 'hearing', s.state.position, 'Busca ativa encontrou o jogador.')
            if event:
                s._events.append(event)
                s.on_perception(event)
        event = dict(operation='search', actor_id=actor_id, changed=found, perceptible=False,
                     dice=list(roll.dice), total=roll.total, dc=dc, found=found, automatic=False,
                     advantage=roll.advantage, disadvantage=roll.disadvantage)
        self.last_search[actor_id] = {**event, 'revision': self.revision, 'player_position': [s.state.position.x + 1, s.state.position.y + 1]}
        logger.info('perception.search_resolved', extra={'data': event})
        return event

    def context(self):
        return dict(hidden=self.hidden_total is not None, revision=self.revision, stealth_total=self.hidden_total, last_search=deepcopy(self.last_search),
                    observers=[dict(id=o.id, name=o.name, column=o.position.x + 1, row=o.position.y + 1,
                                    sleeping=self.sleeping(o), senses={**o.senses.context(self.bonus(o)), 'sleeping': self.sleeping(o)},
                                    awareness=deepcopy(self.awareness.get(o.id, {}))) for o in self.observers()])

src/trama/application/situations.py:
"""Situações reproduzíveis do simulador, preparadas por operações públicas reais."""

from collections import deque
from copy import deepcopy
from dataclasses import asdict
from importlib.resources import files
import json
import logging
import re

from trama.application.dialogue import DialogueMessage
from trama.application.intents import (ActionPlan, DoorIntent, MovementIntent,
                                       MovementSegment, NarrativeIntent, RuleIntent, ScenarioIntent)
from trama.knowledge import Claim
from trama.observability import current_context, log_context, new_id

logger = logging.getLogger(__name__)


class SituationError(ValueError):
    """Uma declaração ou preparação não corresponde à situação esperada."""


class ScriptedRoller:
    """Sequência estrita de [faces, valor]; sem sorteio substituto ao esgotar."""

    def __init__(self, rolls, optional_tail=()):
        if (not isinstance(rolls, list) or not isinstance(optional_tail, (list, tuple)) or
                any(not isinstance(r, list) or len(r) != 2 or
               any(type(n) is not int for n in r) or r[0] < 2 or not 1 <= r[1] <= r[0]
               for r in [*rolls, *optional_tail])):
            raise SituationError('Cada rolagem deve declarar [faces, valor] válidos.')
        self._rolls = deepcopy(rolls)
        self._optional = deepcopy(optional_tail)
        self.reset()

    def reset(self):
        self.pending = deque(tuple(r) for r in self._rolls)
        self.optional_tail = deque(tuple(r) for r in self._optional)
        self.used = []
        self.optional_used = []

    def roll(self, sides):
        queue = self.pending if self.pending else self.optional_tail
        if not queue:
            raise SituationError(f'Rolagem não prevista: d{sides}.')
        expected_sides, value = queue[0]
        if sides != expected_sides:
            raise SituationError(f'Esperava d{expected_sides}, recebeu d{sides}.')
        queue.popleft()
        if queue is self.optional_tail:
            self.optional_used.append([sides, value])
        self.used.append([sides, value])
        return value


def situation_state(session):
    """Observação mecânica da dungeon, sem calcular resultados esperados."""
    area = session.scene.area_at(session.state.position) if session.scene else None
    dungeon = getattr(session, 'dungeon', None)
    return {
        'social': session.social.context(tuple(session.social.profiles)),
        'knowledge': session.knowledge.store.export(),
        'sensing': session.perception.context(),
        'parley': session.parley.context() if session.parley else None,
        'position': [session.state.position.x + 1, session.state.position.y + 1],
        'area': area.id if area else None, 'mode': session.mode.value,
        'spent_meters': float(session.state.spent_meters),
        'remaining_meters': float(session.state.remaining_meters), 'dash_used': session.state.dash_used,
        'combat': session.combat_context(),
        'creatures': {c.id: [c.position.x + 1, c.position.y + 1] for c in session.creatures},
        'resources': {id: asdict(state) for id, state in session.encounter.states.items()},
        'budgets': {id: asdict(budget) for id, budget in session.encounter.budgets.items()},
        'inventory': sorted(getattr(dungeon, 'inventory', set())), 'discovered': sorted(getattr(dungeon, 'discovered', set())),
        'clothing': getattr(dungeon, 'clothing', 'none'), 'weapons': list(session.encounter.player_sheet.weapons),
        'passages': {p.id: {'is_open': p.is_open, 'locked': p.locked} for p in session.scene.passages} if session.scene else {},
        'last_attack': deepcopy(session.encounter.last_attacks.get('player')),
        'prisoner_awake': getattr(dungeon, 'prisoner_awake', False),
        'prisoner_free': getattr(dungeon, 'prisoner_free', False),
        'escaped': getattr(dungeon, 'escaped', False),
        'disguise': getattr(dungeon, 'disguise', 'untested'), 'guard_alert': getattr(dungeon, 'guard_alert', False),
        'sword_concealed': getattr(dungeon, 'sword_concealed', False),
        'pending_opportunity': session.pending_opportunity is not None,
    }


def declared_intent(data):
    values = dict(data)
    kind = values.pop('intent')
    if kind == 'movement':
        values['segments'] = tuple(MovementSegment(**s) for s in values.get('segments', []))
        values.setdefault('dash', False)
        values.setdefault('clarification', '')
        return MovementIntent(**values)
    if kind == 'narrative' and 'claims' in values:
        values['claims'] = tuple(Claim(**c) for c in values['claims'])
    constructors = {'door': DoorIntent, 'scenario': ScenarioIntent, 'rule': RuleIntent, 'narrative': NarrativeIntent}
    if kind not in constructors:
        raise SituationError(f'Tipo de intenção desconhecido: {kind}.')
    return constructors[kind](**values)


class Situation:
    """Dados de preparação; não contém prompts, adaptadores ou critérios de sucesso live."""

    fields = {'id', 'scenario', 'setup', 'rolls', 'optional_world_rolls', 'preparation_rolls',
              'preconditions', 'passage_variations', 'history', 'start_variation', 'sense_variations', 'lighting_variations',
              'knowledge_variations', 'object_variations', 'social_variations'}

    def __init__(self, data, preparations):
        if not isinstance(data, dict) or not isinstance(preparations, dict):
            raise SituationError('Situação e preparações devem ser objetos.')
        if set(data) - self.fields:
            raise SituationError('Campo de situação desconhecido.')
        if not {'id', 'scenario', 'setup', 'rolls', 'preparation_rolls', 'preconditions'} <= data.keys():
            raise SituationError('Situação incompleta.')
        self.data = deepcopy(data)
        self.preparations = deepcopy(preparations)
        if (not isinstance(data['id'], str) or not data['id'] or
                (not isinstance(data['scenario'], str) or not re.fullmatch(r'[a-z0-9_-]+\.json', data['scenario'])) or not isinstance(data['setup'], list) or
                any(not isinstance(name, str) or name not in preparations for name in data['setup']) or
                type(data['preparation_rolls']) is not int or data['preparation_rolls'] < 0 or
                not isinstance(data['preconditions'], dict) or
                any(not isinstance(k, str) or not k for k in data['preconditions'])):
            raise SituationError('Identificação, cenário ou preparação de situação inválidos.')
        if not files('trama').joinpath('scenarios', data['scenario']).is_file():
            raise SituationError('O cenário da situação não existe no pacote.')
        self.new_roller()  # Valida antes de abrir serviços ou executar operações.
        history = data.get('history')
        if history is not None and (not isinstance(history, dict) or set(history) != {'source', 'messages'}
                                    or not isinstance(history['source'], dict) or not history['source'] or
                                    not isinstance(history['messages'], list)):
            raise SituationError('Histórico registrado exige origem e mensagens.')
        self.initial_history = tuple(DialogueMessage.from_data(m) for m in history['messages']) if history else ()
        for name in data['setup']:
            if not isinstance(preparations[name], list) or not preparations[name]:
                raise SituationError(f'Preparação vazia ou inválida: {name}.')
            for declared in preparations[name]:
                if (not isinstance(declared, dict) or
                        set(declared) - {'steps', 'expected_status', 'expected_world_operations'} or
                        declared.get('expected_status') not in {'completed', 'blocked', 'already_satisfied'} or
                        not isinstance(declared.get('steps'), list) or
                        not isinstance(declared.get('expected_world_operations', []), list) or
                        any(not isinstance(op, str) for op in declared.get('expected_world_operations', [])) or
                        (declared['expected_status'] == 'blocked' and not declared.get('expected_world_operations'))):
                    raise SituationError(f'Preparação inválida: {name}.')
                ActionPlan(tuple(declared_intent(s) for s in declared['steps']))

    def new_roller(self):
        return ScriptedRoller(self.data['rolls'], self.data.get('optional_world_rolls', []))

    def scenario_data(self):
        data = json.loads(files('trama').joinpath('scenarios', self.data['scenario']).read_text(encoding='utf-8'))
        if 'start_variation' in self.data:
            data['start'] = deepcopy(self.data['start_variation'])
        for id, variation in self.data.get('sense_variations', {}).items():
            actor = next((a for a in [*data.get('creatures', []), *data.get('observers', [])] if a['id'] == id), None)
            if actor is None or not isinstance(variation, dict):
                raise SituationError(f'Variação de sentidos inválida: {id}.')
            actor['senses'] = {**actor.get('senses', {}), **variation}
        for id, memories in self.data.get('knowledge_variations', {}).items():
            actor = next((a for a in [*data.get('creatures', []), *data.get('observers', [])] if a['id'] == id), None)
            if actor is None or not isinstance(memories, list):
                raise SituationError(f'Variação de conhecimento inválida: {id}.')
            actor['knowledge'] = deepcopy(memories)
        for id, profile in self.data.get('social_variations', {}).items():
            actor = next((a for a in [*data.get('creatures', []), *data.get('observers', [])] if a['id'] == id), None)
            if actor is None or not isinstance(profile, dict):
                raise SituationError(f'Variação social inválida: {id}.')
            actor['social'] = deepcopy(profile)
        for id, variation in self.data.get('object_variations', {}).items():
            obj = next((o for o in data.get('objects', []) if o['id'] == id), None)
            if obj is None or not isinstance(variation, dict) or set(variation) != {'position'}:
                raise SituationError(f'Variação de objeto inválida: {id}.')
            obj['position'] = deepcopy(variation['position'])
        for kind, positions in self.data.get('lighting_variations', {}).items():
            if kind not in {'dark', 'dim'} or not isinstance(positions, list):
                raise SituationError('Variação de iluminação inválida.')
            data[kind] = deepcopy(positions)
        for id, variation in self.data.get('passage_variations', {}).items():
            passage = next((p for p in data['passages'] if p['id'] == id), None)
            if (passage is None or not isinstance(variation, dict) or
                    variation.keys() - {'is_open', 'locked', 'description'}
                    or any(type(v) is not bool for k, v in variation.items() if k != 'description')
                    or ('description' in variation and not isinstance(variation['description'], str))):
                raise SituationError(f'Variação de passagem inválida: {id}.')
            passage.update(variation)
        return data

    def prepare(self, conversation, roller):
        """Executa operações reais e recusa deriva de estado, dados ou etapas pendentes."""
        for name in self.data['setup']:
            for index, declared in enumerate(self.preparations[name]):
                report = conversation.execute(ActionPlan(tuple(declared_intent(s) for s in declared['steps'])))
                operations = {e['operation'] for e in report.world_events}
                if (report.status != declared['expected_status'] or report.failures or report.unperformed_steps or
                        not set(declared.get('expected_world_operations', [])) <= operations or
                        conversation.session.pending_opportunity or conversation.pending_npc_turn):
                    raise SituationError(f'Preparação inválida de {self.data["id"]}, {name}[{index}]: {report.stop_reason}')
        if len(roller.used) != self.data['preparation_rolls']:
            raise SituationError('A preparação consumiu uma sequência de dados diferente.')
        actual = situation_state(conversation.session)
        for path, expected in self.data['preconditions'].items():
            value = actual
            for key in path.split('.'):
                if not isinstance(value, dict) or key not in value:
                    raise SituationError(f'pré-condição desconhecida: {path}.')
                value = value[key]
            if type(value) is not type(expected) or value != expected:
                # Números JSON inteiros/decimais representam a mesma medida.
                if not (type(value) in {int, float} and type(expected) in {int, float} and value == expected):
                    raise SituationError(f'pré-condição {path}: esperado {expected!r}, obtido {value!r}.')
        logger.info('situation.prepared', extra={'data': {'situation_id': self.data['id'],
                    'preparation_dice_used': len(roller.used), 'state': actual}})

    def initialize(self, conversation, roller):
        """Usado na abertura e no reinício, com a mesma sequência e validação."""
        with log_context(interaction_id=current_context().get('interaction_id') or new_id()):
            roller.reset()
            logger.info('situation.preparation_started', extra={'data': {
                'situation_id': self.data['id'], 'state': situation_state(conversation.session)}})
            try:
                self.prepare(conversation, roller)
            except Exception:
                logger.exception('situation.preparation_failed', extra={'data': {'situation_id': self.data['id']}})
                raise

    def restore_history(self, conversation):
        conversation.extend_history(self.initial_history)


def load_situation(id):
    catalog = json.loads(files('trama').joinpath('scenarios', 'situations.json').read_text(encoding='utf-8'))
    if type(catalog.get('schema_version')) is not int or catalog['schema_version'] != 1:
        raise SituationError('Versão de catálogo de situações não suportada.')
    matches = [s for s in catalog['situations'] if s['id'] == id]
    if len(matches) != 1:
        raise SituationError(f'Situação desconhecida ou duplicada: {id}.')
    return Situation(matches[0], catalog['preparations'])

src/trama/scene.py:
"""Geometria, passagens e objetos; sem regras de turno ou visualização."""

from dataclasses import dataclass, replace
import logging
from trama.spatial import Grid, Position

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class Attachment:
    surface: str = "floor"
    side: str | None = None

    def __post_init__(self) -> None:
        if (self.surface not in {"floor", "wall"}
                or (self.surface == "floor" and self.side is not None)
                or (self.surface == "wall" and self.side not in {"north", "east", "south", "west"})):
            raise ValueError("Fixação inválida: use floor sem lado ou wall com lado cardinal.")


@dataclass(frozen=True)
class SceneObject:
    id: str
    name: str
    position: Position
    kind: str = "object"
    attachment: Attachment = Attachment()
    blocks_movement: bool = False
    blocks_vision: bool = False
    description: str = ""

    def __post_init__(self) -> None:
        if (not self.id or not self.name or not self.kind
                or not isinstance(self.position, Position) or not isinstance(self.attachment, Attachment)
                or type(self.blocks_movement) is not bool or type(self.blocks_vision) is not bool):
            raise ValueError("Objeto de cenário inválido.")


@dataclass(frozen=True)
class Area:
    id: str
    name: str
    x: int
    y: int
    width: int
    height: int
    description: str = ""

    def __post_init__(self) -> None:
        if not self.id or not self.name or self.width <= 0 or self.height <= 0:
            raise ValueError("Um lugar deve ter identificador, nome e dimensões positivas.")

    @property
    def cells(self) -> frozenset[Position]:
        return frozenset(Position(x, y) for y in range(self.y, self.y + self.height)
                         for x in range(self.x, self.x + self.width))


@dataclass(frozen=True)
class Passage:
    id: str
    name: str
    kind: str
    position: Position
    is_open: bool
    locked: bool
    connects: tuple[str, str]
    description: str = ''

    def __post_init__(self) -> None:
        if (not self.id or not self.name or self.kind not in {"gate", "door"}
                or type(self.is_open) is not bool or type(self.locked) is not bool
                or len(self.connects) != 2 or self.connects[0] == self.connects[1]
                or not isinstance(self.description, str) or len(self.description) > 1000):
            raise ValueError("Passagem inválida.")
        if self.is_open and self.locked:
            raise ValueError("Uma passagem aberta não pode estar trancada.")


@dataclass(frozen=True)
class Scene:
    # grid contém somente terreno/passagens. movement_grid acrescenta objetos.
    grid: Grid
    areas: tuple[Area, ...]
    passages: tuple[Passage, ...]
    dim: frozenset[Position] = frozenset()
    dark: frozenset[Position] = frozenset()
    objects: tuple[SceneObject, ...] = ()

    def __post_init__(self) -> None:
        if self.dim & self.dark or any(not self.grid.contains(p) for p in self.dim | self.dark):
            raise ValueError("Iluminação fora do mapa ou sobreposta.")
        ids = [item.id for item in (*self.areas, *self.passages, *self.objects)]
        if len(ids) != len(set(ids)):
            raise ValueError("Os destinos devem ter identificadores únicos.")
        area_ids = {area.id for area in self.areas}
        occupied: set[Position] = set()
        for area in self.areas:
            if any(not self.grid.contains(p) for p in area.cells) or occupied & area.cells:
                raise ValueError("Lugares devem estar dentro do mapa e não podem se sobrepor.")
            occupied.update(area.cells)
        for passage in self.passages:
            if not set(passage.connects) <= area_ids or not self.grid.contains(passage.position):
                raise ValueError("Passagem fora do mapa ou com conexão desconhecida.")
            if passage.is_open == (passage.position in self.grid.blocked):
                raise ValueError("O bloqueio da passagem deve corresponder ao seu estado.")
            p = passage.position
            adjacent = {Position(p.x + dx, p.y + dy)
                        for dx, dy in ((0, -1), (-1, 0), (1, 0), (0, 1))}
            for area in self.areas:
                if area.id in passage.connects and not adjacent & area.cells:
                    raise ValueError("A passagem deve ser adjacente aos dois lugares conectados.")
        passage_cells = {p.position for p in self.passages}
        for obj in self.objects:
            if (not self.grid.contains(obj.position)
                    or (obj.position in self.grid.blocked and obj.position not in passage_cells)):
                raise ValueError("O objeto deve pertencer a uma casa de piso ou passagem do mapa.")
            if obj.attachment.surface == "wall":
                dx, dy = {"north": (0, -1), "east": (1, 0), "south": (0, 1), "west": (-1, 0)}[obj.attachment.side]
                wall = Position(obj.position.x + dx, obj.position.y + dy)
                if self.grid.contains(wall) and (wall not in self.grid.blocked or wall in passage_cells):
                    raise ValueError("Uma fixação na parede exige uma parede no lado indicado.")

    @classmethod
    def from_data(cls, data: dict) -> "Scene":
        areas = tuple(Area(**area) for area in data["areas"])
        passages = tuple(Passage(
            id=p["id"], name=p["name"], kind=p["kind"], position=Position(*p["position"]),
            is_open=p["is_open"], locked=p["locked"], connects=tuple(p["connects"]), description=p.get('description', ''),
        ) for p in data["passages"])
        objects = tuple(SceneObject(
            id=o["id"], name=o["name"], position=Position(*o["position"]),
            kind=o.get("kind", "object"), attachment=Attachment(**o.get("attachment", {})),
            blocks_movement=o.get("blocks_movement", False), blocks_vision=o.get("blocks_vision", False),
            description=o.get("description", ""),
        ) for o in data.get("objects", []))
        floor = frozenset(p for area in areas for p in area.cells)
        floor |= frozenset(p.position for p in passages if p.is_open)
        blocked = frozenset(Position(x, y) for y in range(data["height"])
                            for x in range(data["width"])) - floor
        grid = Grid(data["width"], data["height"], blocked)
        result = cls(grid, areas, passages,
                   frozenset(Position(*p) for p in data.get("dim", [])),
                   frozenset(Position(*p) for p in data.get("dark", [])), objects)
        logger.info("map.loaded", extra={"data": {"width": grid.width, "height": grid.height,
                    "areas": [a.id for a in areas], "passages": [p.id for p in passages],
                    "objects": [o.id for o in objects]}})
        logger.debug("map.objects_loaded", extra={"data": {"objects": objects}})
        return result

    @property
    def movement_blockers(self) -> frozenset[Position]:
        return frozenset(o.position for o in self.objects if o.blocks_movement)

    @property
    def movement_grid(self) -> Grid:
        blockers = self.movement_blockers
        return (replace(self.grid, blocked=self.grid.blocked | blockers,
                        difficult=self.grid.difficult - blockers) if blockers else self.grid)

    @property
    def open_passages_grid(self) -> Grid:
        """Previsão de rota: abre passagens, preservando obstáculos de objetos."""
        blocked = self.grid.blocked - frozenset(p.position for p in self.passages)
        return replace(self.movement_grid, blocked=blocked | self.movement_blockers)

    @property
    def opaque(self) -> frozenset[Position]:
        # Grades impedem passagem quando fechadas, mas permitem ver pelas barras.
        terrain = self.grid.blocked - frozenset(p.position for p in self.passages if p.kind == "gate")
        return terrain | frozenset(o.position for o in self.objects if o.blocks_vision)

    def with_passage(self, passage_id: str, is_open: bool) -> "Scene":
        passage = next((p for p in self.passages if p.id == passage_id), None)
        if passage is None:
            raise ValueError("Passagem desconhecida.")
        updated = replace(passage, is_open=is_open)
        blocked = (self.grid.blocked - {passage.position} if is_open
                   else self.grid.blocked | {passage.position})
        result = replace(self, grid=replace(self.grid, blocked=frozenset(blocked)),
                       passages=tuple(updated if p.id == passage_id else p for p in self.passages))
        logger.debug("map.passage_changed", extra={"data": {"passage_id": passage_id,
                     "before": passage, "after": updated}})
        return result

    def area_at(self, position: Position) -> Area | None:
        return next((area for area in self.areas if position in area.cells), None)

    def destination_cells(self, target_id: str) -> frozenset[Position]:
        blocked = self.movement_grid.blocked
        for area in self.areas:
            if area.id == target_id:
                return area.cells - blocked
        for passage in self.passages:
            if passage.id == target_id:
                p = passage.position
                # "Até" significa aproximar-se pelo lado alcançável, sem atravessar.
                return frozenset(
                    Position(p.x + dx, p.y + dy)
                    for dx, dy in ((0, -1), (-1, 0), (1, 0), (0, 1))
                    if self.grid.contains(Position(p.x + dx, p.y + dy))
                    and Position(p.x + dx, p.y + dy) not in blocked
                )
        for obj in self.objects:
            if obj.id == target_id:
                p = obj.position
                # Aproximação à casa do objeto ou vizinha, sem entrar em casas bloqueadas.
                return frozenset(Position(p.x + dx, p.y + dy)
                                 for dx, dy in ((0, 0), (0, -1), (-1, 0), (1, 0), (0, 1))
                                 if self.grid.contains(Position(p.x + dx, p.y + dy))
                                 and Position(p.x + dx, p.y + dy) not in blocked)
        raise ValueError("O destino informado não existe neste mapa.")

